  const more = [...rows, { id: 'f', name: 'Tuition', due: '2027-01-01', amount: 2000 }];
  assert.deepEqual(page(spec, more, { sort: { field: 'amount', dir: 'desc' }, after: first.next! }).rows.map((r) => r.id), ['b', 'c']);

